import{_ as a,a as t,o as n,a6 as i}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Themes","description":"","frontmatter":{"outline":false,"apiType":"graphql"},"headers":[],"relativePath":"api/graphql-api/admin/appearance/themes/index.md","filePath":"api/graphql-api/admin/appearance/themes/index.md","lastUpdated":1789385991000}'),r={name:"api/graphql-api/admin/appearance/themes/index.md"};function h(s,e,p,d,o,l){return n(),t("div",null,e[0]||(e[0]=[i('<h1 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h1><p>The theme gallery: every theme the installation knows about, and which channels run each of them.</p><p>A theme is either <strong>installed</strong> (its files are on the server and it can be activated), <strong>active</strong> (installed and running on at least one channel), or <strong>available</strong> (listed in the catalog but not installed yet). Installing is a server-side act — the API activates and reports, it does not install.</p><p>Each channel runs exactly one theme. Sections belong to a theme and a channel together, so a channel that switches theme stops drawing the sections built for the old one without losing them.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/appearance/themes/list.html">adminAppearanceThemes</a></td><td>Every theme with its status and channels</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/themes/detail.html">adminAppearanceTheme</a></td><td>One theme by code</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/themes/impact.html">adminAppearanceThemeImpact</a></td><td>Sections a switch would leave behind</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/themes/activate.html">createAdminAppearanceThemeActivate</a></td><td>Point channels at a theme</td></tr></tbody></table><p>See the <a href="/api/graphql-api/admin/appearance/">Appearance overview</a> for how themes and sections fit together.</p>',6)]))}const g=a(r,[["render",h]]);export{m as __pageData,g as default};
